hpy-012.text:
To implement the cron expression parser, I will first validate and parse each of the five fields into sets of valid values. For each field, I'll handle `*`, numbers, ranges (`a-b`), step values (`*/s`, `a-b/s`), and comma-separated lists. Special attention is needed for the day-of-month/day-of-week interaction: when both are restricted (i.e., not `*`), the day matches if *either* field matches; otherwise, only the restricted one applies. I'll iterate forward from `after`, incrementing minute-by-minute (or more efficiently by jumping to candidate minutes), and check if the datetime matches all five fields according to the day rule. Edge cases include invalid ranges (e.g., `30-10`), out-of-range values, and leap years.

```python
from datetime import datetime, timedelta

def next_fire(expr, after):
    def parse_field(field_str, min_val, max_val):
        if field_str == '*':
            return set(range(min_val, max_val + 1))
        values = set()
        parts = field_str.split(',')
        for part in parts:
            if '/' in part:
                range_part, step_str = part.split('/')
                step = int(step_str)
                if step <= 0:
                    raise ValueError("Invalid step value")
                if range_part == '*':
                    start, end = min_val, max_val
                elif '-' in range_part:
                    try:
                        start_str, end_str = range_part.split('-')
                        start, end = int(start_str), int(end_str)
                    except:
                        raise ValueError("Invalid range in step expression")
                else:
                    raise ValueError("Invalid range for step expression")
                if start < min_val or end > max_val or start > end:
                    raise ValueError("Range out of bounds")
                values.update(range(start, end + 1, step))
            elif '-' in part:
                try:
                    start_str, end_str = part.split('-')
                    start, end = int(start_str), int(end_str)
                except:
                    raise ValueError("Invalid range")
                if start < min_val or end > max_val or start > end:
                    raise ValueError("Range out of bounds")
                values.update(range(start, end + 1))
            else:
                try:
                    val = int(part)
                except:
                    raise ValueError("Invalid value")
                if val < min_val or val > max_val:
                    raise ValueError("Value out of bounds")
                values.add(val)
        return values

    try:
        fields = expr.strip().split()
        if len(fields) != 5:
            raise ValueError("Cron expression must have exactly 5 fields")
        minute_str, hour_str, day_str, month_str, dow_str = fields

        minutes = parse_field(minute_str, 0, 59)
        hours = parse_field(hour_str, 0, 23)
        days = parse_field(day_str, 1, 31)
        months = parse_field(month_str, 1, 12)
        dows = parse_field(dow_str, 0, 6)

        # Determine if day-of-month and day-of-week are restricted
        dom_restricted = day_str != '*'
        dow_restricted = dow_str != '*'

    except Exception as e:
        if isinstance(e, ValueError):
            raise
        else:
            raise ValueError("Malformed cron expression")

    # Start from the next minute after `after`
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Limit iterations to avoid infinite loops (e.g., invalid expressions)
    max_iterations = 10 * 365 * 24 * 60  # ~10 years in minutes
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        # Check month
        if current.month not in months:
            # Jump to next month boundary
            if current.month == 12:
                current = datetime(current.year + 1, 1, 1, 0, 0)
            else:
                current = datetime(current.year, current.month + 1, 1, 0, 0)
            continue

        # Check day-of-week and day-of-month
        current_dow = current.weekday()
        if current_dow == 6:  # Python Monday=0, Sunday=6 → convert to cron (Sunday=0)
            current_dow = 0
        else:
            current_dow += 1

        dom_match = current.day in days
        dow_match = current_dow in dows

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        elif dom_restricted:
            day_match = dom_match
        elif dow_restricted:
            day_match = dow_match
        else:
            day_match = True

        if not day_match:
            # Jump to next possible day
            current = datetime(current.year, current.month, current.day + 1, 0, 0)
            continue

        # Check hour
        if current.hour not in hours:
            # Find next valid hour
            for h in sorted(hours):
                if h > current.hour:
                    current = datetime(current.year, current.month, current.day, h, 0)
                    break
            else:
                # Next day
                try:
                    current = datetime(current.year, current.month, current.day + 1, min(hours), 0)
                except ValueError:
                    # End of month
                    if current.month == 12:
                        current = datetime(current.year + 1, 1, 1, min(hours), 0)
                    else:
                        current = datetime(current.year, current.month + 1, 1, min(hours), 0)
            continue

        # Check minute
        if current.minute not in minutes:
            for m in sorted(minutes):
                if m > current.minute:
                    try:
                        current = datetime(current.year, current.month, current.day, current.hour, m)
                    except ValueError:
                        # Shouldn't happen with valid minutes/hours
                        current = datetime(current.year, current.month, current.day + 1, min(hours), m)
                    break
            else:
                # Next hour
                for h in sorted(hours):
                    if h > current.hour:
                        try:
                            current = datetime(current.year, current.month, current.day, h, min(minutes))
                        except ValueError:
                            if current.month == 12:
                                current = datetime(current.year + 1, 1, 1, h, min(minutes))
                            else:
                                current = datetime(current.year, current.month + 1, 1, h, min(minutes))
                        break
                else:
                    # Next day
                    try:
                        current = datetime(current.year, current.month, current.day + 1, min(hours), min(minutes))
                    except ValueError:
                        if current.month == 12:
                            current = datetime(current.year + 1, 1, 1, min(hours), min(minutes))
                        else:
                            current = datetime(current.year, current.month + 1, 1, min(hours), min(minutes))
            continue

        # All fields match
        return current

    raise ValueError("No matching time found within search limit")

```

