            current = datetime(current.year, current.month, current.day + 1, 0, 0)
            continue

        # Check hour
        if current.hour not in hours:
            # Find next valid hour
            for h in sorted(hours):
                if h > current.hour:
                    current = datetime(current.year, current.month, current.day, h, 0)
