                    try:
                        current = datetime(current.year, current.month, current.day, current.hour, m)
                    except ValueError:
                        # Shouldn't happen with valid minutes/hours
                        current = datetime(current.year, current.month, current.day + 1, min(hours), m)
                    break
            else:
                # Next hour
                for h in sorted(hours):
                    if h > current.hour:
                        try:
                            current = datetime(current.year, current.month, current.day, h, min(minutes))
                        except ValueError:
                            if current.month == 12:
                                current = datetime(current.year + 1, 1, 1, h, min(minutes))
