To efficiently compute sliding window medians for large inputs, I'll use two heaps: a max-heap (simulated with negative values in Python's min-heap) for the lower half of numbers and a min-heap for the upper half. This allows O(log k) insertion and O(1) median retrieval. I'll maintain balance so that the size difference between heaps is at most 1, and lazily remove elements that fall outside the current window using a dictionary to track outgoing values. Edge cases include k=1 (median is just the element), k > len(a) (return empty list), and even/odd k handling for median calculation.

```
import heapq
from collections import defaultdict

def window_medians(a, k):
    if k > len(a) or k <= 0:
        return []

    # Max heap for lower half (store negatives), min heap for upper half
    low = []  # max-heap (negated values)
    high = []  # min-heap
    to_remove = defaultdict(int)

    def balance_heaps():
        # Ensure low has at least as many elements as high, and size diff <= 1
        while len(low) > len(high) + 1:
            val = -heapq.heappop(low)
            heapq.heappush(high, val)
        while len(high) > len(low):
            val = heapq.heappop(high)
            heapq.heappush(low, -val)

    def clean_heaps():
        while low and to_remove[-low[0]] > 0:
            val = -heapq.heappop(low)
            to_remove[val] -= 1
        while high and to_remove[high[0]] > 0:
            val = heapq.heappop(high)
            to_remove[val] -= 1

    # Initialize heaps with first window
    for i in range(k):
        heapq.heappush(low, -a[i])

    # Move elements to balance: low should have ceil(k/2) elements
    for _ in range((k + 1) // 2):
        val = -heapq.heappop(low)
        heapq.heappush(high, val)

    result = []

    for i in range(k - 1, len(a)):
        clean_heaps()

        # Calculate median
        if k % 2 == 1:
            median = float(-low[0])
        else:
            median = (-low[0] + high[0]) / 2.0
        result.append(median)

        # Remove element going out of window (if not last iteration)
        if i < len(a) - 1:
            out_val = a[i - k + 1]
            to_remove[out_val] += 1

            # Rebalance heaps after removal
            if out_val <= -low[0]:
                # Was in low heap
                if out_val == -low[0]:
                    heapq.heappop(low)
                else:
                    # Mark for removal, will be cleaned later
                    pass
            else:
                # Was in high heap
                if out_val == high[0]:
                    heapq.heappop(high)
                else:
                    # Mark for removal
                    pass

            # Add new element
            in_val = a[i + 1]

            # Determine which heap to add to
            if not low or in_val <= -low[0]:
                heapq.heappush(low, -in_val)
            else:
                heapq.heappush(high, in_val)

            # Rebalance
            balance_heaps()

    return result
