import heapq

def merge_sorted(iterables):
    # Create a heap of (value, source_index, iterator)
    heap = []
    for idx, it in enumerate(iterables):
        try:
            value = next(it)
            heapq.heappush(heap, (value, idx, it))
        except StopIteration:
            pass  # Skip empty iterables

    while heap:
        value, idx, it = heapq.heappop(heap)
        yield value
        try:
            next_value = next(it)
            heapq.heappush(heap, (next_value, idx, it))
        except StopIteration:
            pass  # This source is exhausted
```

