hjs-002.text:
I'll implement `pLimit(n)` using a queue-based approach with a counter to track active promises. The function will return a wrapper that accepts a zero-argument promise-returning function. Internally, I'll maintain a queue of pending jobs and an active count to ensure at most `n` promises run concurrently. When a promise resolves or rejects, the next queued job will start immediately to maintain concurrency without leaving slots occupied. Edge cases handled include: n ≤ 0 (no concurrent jobs), rejection not affecting the queue, and proper ordering via FIFO queue.

ANSWER:
```javascript
function pLimit(n) {
  if (typeof n !== 'number' || n < 0) {
    throw new Error('Expected a non-negative number');
  }

  let activeCount = 0;
  const queue = [];

  function next() {
    if (queue.length === 0 || activeCount >= n) return;

    activeCount++;
    const { fn, resolve, reject } = queue.shift();

    try {
      Promise.resolve(fn()).then(
        (value) => {
          activeCount--;
          resolve(value);
          next();
        },
        (error) => {
          activeCount--;
          reject(error);
          next();
        }
      );
    } catch (error) {
      activeCount--;
      reject(error);
      next();
    }
  }

  return function (fn) {
    if (typeof fn !== 'function') {
      throw new Error('Expected a function');
    }

    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };
}

module.exports = pLimit;
```

