hjs-003.text:
I need to implement a debounce function that handles leading/trailing execution modes carefully. The key challenge is ensuring that when both `leading` and `trailing` are true, a single call fires only once (at the leading edge), while multiple rapid calls fire twice (once at leading, once at trailing after the wait period). I'll track the last invocation time and arguments to ensure `this` context and latest arguments are preserved for trailing calls. I'll also handle edge cases like canceling during a pending trailing call, and ensure `.flush()` returns the result of the actual invocation (or undefined if nothing was invoked). The implementation will use `setTimeout` for scheduling and clear it appropriately on cancel/flush.

ANSWER:
```javascript
function debounce(fn, wait, options) {
  let timeoutId = null;
  let lastArgs = null;
  let lastThis = null;
  let result = undefined;
  let leadingCalled = false;

  const later = () => {
    const elapsed = Date.now() - lastCallTime;
    if (elapsed < wait && leading) {
      // Still within the wait period and leading was called, schedule trailing
      timeoutId = setTimeout(later, wait - elapsed);
    } else {
      // Time to execute trailing
      timeoutId = null;
      if (!leading || leadingCalled) {
        result = fn.apply(lastThis, lastArgs);
        lastArgs = null;
        lastThis = null;
      }
      leadingCalled = false;
    }
  };

  const debounced = function(...args) {
    lastArgs = args;
    lastThis = this;

    const callNow = leading && !timeoutId;

    if (!timeoutId) {
      lastCallTime = Date.now();
      if (callNow) {
        result = fn.apply(lastThis, lastArgs);
        leadingCalled = true;
        lastArgs = null;
        lastThis = null;
      } else {
        timeoutId = setTimeout(later, wait);
      }
    } else if (trailing) {
      // Reset timeout to ensure trailing call happens after full wait period
      clearTimeout(timeoutId);
      timeoutId = setTimeout(later, wait);
    }

    return result;
  };

  const { leading = false, trailing = true } = options || {};

  debounced.cancel = function() {
    clearTimeout(timeoutId);
    timeoutId = null;
    lastArgs = null;
    lastThis = null;
  };

  debounced.flush = function() {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      result = fn.apply(lastThis, lastArgs);
      lastArgs = null;
      lastThis = null;
    }
    return result;
  };

  // Redefine with correct leading/trailing values
  Object.defineProperty(debounced, 'leading', { value: leading });
  Object.defineProperty(debounced, 'trailing', { value: trailing });

  return debounced;
}

module.exports = debounce;
```

