  if (pointer === '') return doc;
  if (!pointer.startsWith('/')) throw new Error('JSON Pointer must start with "/"');

  const tokens = pointer.slice(1).split('/');
  let current = doc;

  for (const token of tokens) {
    if (current === undefined || current === null) return undefined;

    // Decode token: ~1 -> /, ~0 -> ~ (order matters: decode ~0 first to avoid double-decoding)
    const decodedToken = token.replace(/~1/g, '/').replace(/~0/g, '~');

    if (Array.isArray(current)) {
      const index = parseInt(decodedToken, 10);
      if (decodedToken === '-' || isNaN(index)) return undefined;
      current = current[index];
    } else if (current !== null && typeof current === 'object') {
      current = current[decodedToken];
    } else {
      return undefined;
    }
  }

  return current;
}

function set(doc, pointer, value) {
  if (pointer === '') {
    return doc;
  }
  if (!pointer.startsWith('/')) throw new Error('JSON Pointer must start with "/"');

  const tokens = pointer.slice(1).split('/');
  let current = doc;

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    // Decode token: ~1 -> /, ~0 -> ~ (order matters)
    const decodedToken = token.replace(/~1/g, '/').replace(/~0/g, '~');

    if (i === tokens.length - 1) {
      // Last token: set the value
      if (Array.isArray(current)) {
        const index = parseInt(decodedToken, 10);
        if (decodedToken === '-') {
          current.push(value);
        } else if (!isNaN(index)) {
          current[index] = value;
        }
      } else if (current !== null && typeof current === 'object') {
        current[decodedToken] = value;
      }
    } else {
      // Intermediate token: create if missing
      if (Array.isArray(current)) {
        const index = parseInt(decodedToken, 10);
        if (decodedToken === '-' || isNaN(index)) {
          // For arrays, create object at index
          while (current.length <= index) current.push({});
          if (!current[index] || typeof current[index] !== 'object') {
            current[index] = {};
          }
          current = current[index];
        } else {
          if (!current[index]) {
            current[index] = {};
          }
          current = current[index];
        }
      } else if (current !== null && typeof current === 'object') {
        if (!current[decodedToken]) {
          current[decodedToken] = {};
        }
        current = current[decodedToken];
      } else {
        // Can't traverse through non-object/non-array
        throw new Error('Cannot set value: intermediate path is not an object or array');
