  constructor() {
    this.listeners = new Map();
    this.pendingAdditions = [];
    this.pendingRemovals = new Set();
  }

  on(event, fn) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const list = this.listeners.get(event);
    list.push(fn);

    return () => {
      if (this.inEmit) {
        this.pendingRemovals.add({ event, fn });
      } else {
        const list = this.listeners.get(event);
        if (list) {
          const idx = list.indexOf(fn);
          if (idx > -1) list.splice(idx, 1);
        }
      }
    };
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      return fn(...args);
    };
    wrapper.__once = true;
    return this.on(event, wrapper);
  }

  off(event, fn) {
    if (this.inEmit) {
      this.pendingRemovals.add({ event, fn });
    } else {
      const list = this.listeners.get(event);
      if (list) {
        const idx = list.indexOf(fn);
        if (idx > -1) list.splice(idx, 1);
      }
    }
  }

  emit(event, ...args) {
    const list = this.listeners.get(event);
    if (!list || list.length === 0) return 0;

    // Snapshot listeners to avoid interference from concurrent modifications
    const snapshot = [...list];
    let error = null;
    let count = 0;

    this.inEmit = true;

    try {
      for (const fn of snapshot) {
        // Skip if removed during emit
        if (this.pendingRemovals.has({ event, fn })) continue;

        try {
          fn(...args);
          count++;
        } catch (e) {
          if (!error) error = e;
        }
      }

      // Process pending removals
      for (const { event: ev, fn } of this.pendingRemovals) {
        const list = this.listeners.get(ev);
        if (list) {
          const idx = list.indexOf(fn);
          if (idx > -1) list.splice(idx, 1);
        }
      }

      // Process pending additions
      for (const { event: ev, fn } of this.pendingAdditions) {
        if (!this.listeners.has(ev)) {
          this.listeners.set(ev, []);
        }
        this.listeners.get(ev).push(fn);
      }

    } finally {
      this.pendingRemovals.clear();
      this.pendingAdditions = [];
      this.inEmit = false;
    }

    if (error) throw error;
    return count;
  }
}

