  function makeProxy(obj, path = []) {
    return new Proxy(obj, {
      get(targetObj, prop, receiver) {
        if (prop === Symbol.toPrimitive || prop === 'toString' || prop === 'valueOf') {
          return Reflect.get(targetObj, prop, receiver);
        }
        const value = Reflect.get(targetObj, prop, receiver);
        if (value !== null && typeof value === 'object') {
          return makeProxy(value, path.concat(prop));
        }
        return value;
      },
      set(targetObj, prop, newValue, receiver) {
        const oldValue = Reflect.has(targetObj, prop) ? targetObj[prop] : undefined;
        if (Object.is(newValue, oldValue)) {
          return true;
        }
        const result = Reflect.set(targetObj, prop, newValue, receiver);
        if (result) {
          onChange(path.concat(prop), newValue, oldValue);
        }
        return result;
