        const result = Reflect.deleteProperty(targetObj, prop);
        if (result) {
          onChange(path.concat(prop), undefined, oldValue);
        }
        return result;
      }
    });
  }

  if (target === null || typeof target !== 'object') {
    throw new Error('Target must be a plain object');
  }
  return makeProxy(target);
