I need to implement a memoization function that handles caching based on either a provided key function or an automatic strategy. When no keyFn is given, I'll use WeakMap for object arguments (to avoid memory leaks) and regular Map for primitives. For objects, distinct references are treated as different keys even if they have the same content. If a function call throws an error, that result is not cached—only successful returns are stored. I'll track the number of actual function calls (cache misses) in a `.calls` property and provide a `.clear()` method to reset the cache. Edge cases include: handling non-callable inputs, ensuring primitives are properly distinguished (e.g., 0 vs "0"), and making sure WeakMap keys are truly objects.

ANSWER:
```javascript
function memoize(fn, keyFn) {
  if (typeof fn !== 'function') {
    throw new TypeError('fn must be a function');
  }

  const cache = new Map();
  const weakCache = new WeakMap();
  let calls = 0;

  function getCacheKey(args) {
    if (keyFn) {
      return keyFn(...args);
    }

    if (args.length !== 1) {
      // For multiple arguments without keyFn, use a composite key
      return JSON.stringify(args);
    }

    const arg = args[0];
    if (arg !== null && typeof arg === 'object') {
      return arg;
    }

    // For primitives, use the value itself as key
    return arg;
  }

  function getCache(arg) {
    if (keyFn || (arg.length !== 1)) {
      return cache;
    }

    const arg0 = arg[0];
    if (arg0 !== null && typeof arg0 === 'object') {
      return weakCache;
    }

    return cache;
  }

  function memoized(...args) {
    const cacheMap = getCache(args);
    const key = getCacheKey(args);

    if (cacheMap.has(key)) {
      return cacheMap.get(key);
    }

    calls++;
    const result = fn(...args);
    cacheMap.set(key, result);
    return result;
  }

  memoized.cache = cache;
  memoized.weakCache = weakCache;
  Object.defineProperty(memoized, 'calls', {
    get: () => calls
  });

  memoized.clear = function() {
    cache.clear();
    weakCache.clear();
    calls = 0;
  };

  return memoized;
}

module.exports = memoize;
```

