hjs-013.text:
I'll implement `parseQuery` to handle PHP/qs-style bracket notation by recursively building nested structures: bare repeated keys become arrays, bracketed numeric indices create arrays (with sparse handling), and bracketed string keys create nested objects. I'll decode percent-encoding and convert `+` to spaces, treating missing values as empty strings. For `buildQuery`, I'll traverse the object recursively, sorting keys to ensure deterministic output, and encode values with proper percent-encoding while handling arrays and nested objects appropriately. Edge cases include empty keys, mixed array/object notation (e.g., `a[0][b]=1`), and ensuring round-trip consistency by normalizing array indices.

ANSWER:
```javascript
function parseQuery(qs) {
  if (!qs) return {};
  if (qs.startsWith('?')) qs = qs.slice(1);

  const result = {};

  for (const part of qs.split('&')) {
    if (!part) continue;

    let [rawKey, rawValue] = part.split('=');
    rawKey = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    rawValue = rawValue !== undefined ? decodeURIComponent(rawValue.replace(/\+/g, ' ')) : '';

    let current = result;
    const keys = rawKey.split('[');

    for (let i = 0; i < keys.length; i++) {
      let key = keys[i];

      if (i === keys.length - 1) {
        // Last segment: assign value
        const lastBracket = key.lastIndexOf(']');
        if (lastBracket !== -1) {
          key = key.slice(0, lastBracket);
        }

        if (key === '') {
          // Empty key from trailing bracket, treat as array index 0
          if (!Array.isArray(current)) {
            current = [];
          }
          current[0] = rawValue;
        } else if (/^\d+$/.test(key)) {
          // Numeric index
          if (!Array.isArray(current)) {
            current = [];
          }
          current[parseInt(key, 10)] = rawValue;
        } else {
          // String key
          if (!current.hasOwnProperty(key)) {
            current[key] = rawValue;
          } else if (Array.isArray(current[key])) {
            current[key].push(rawValue);
          } else {
            current[key] = [current[key], rawValue];
          }
        }
      } else {
        // Nested key
        const bracketEnd = key.indexOf(']');
        if (bracketEnd !== -1) {
          key = key.slice(0, bracketEnd);
        }

        if (key === '') {
          // Empty key means array
          if (!Array.isArray(current)) {
            current = [];
          }
        } else if (/^\d+$/.test(key)) {
          // Numeric index
          const idx = parseInt(key, 10);
          if (!Array.isArray(current)) {
            current = [];
          }
          if (current[idx] === undefined) {
            current[idx] = {};
          }
          current = current[idx];
        } else {
          // String key
          if (!current.hasOwnProperty(key)) {
            current[key] = {};
          } else if (Array.isArray(current[key])) {
            // If it's an array, create new object at end
            current[key].push({});
            current = current[key][current[key].length - 1];
          } else {
            current = current[key];
          }
        }
      }
    }
  }

  return result;
}

