  const parts = [];

  function encode(str) {
    return encodeURIComponent(String(str)).replace(/%20/g, '+');
  }

  function traverse(current, prefix) {
    if (current === null || current === undefined) return;

    const keys = Object.keys(current).sort();

    for (const key of keys) {
      const value = current[key];
      const newPrefix = prefix ? `${prefix}[${key}]` : key;

      if (Array.isArray(value)) {
        for (let i = 0; i < value.length; i++) {
          if (value[i] !== null && typeof value[i] === 'object') {
            traverse(value[i], `${newPrefix}[]`);
          } else {
            parts.push(`${encode(newPrefix)}=${value[i] !== undefined ? encode(value[i]) : ''}`);
          }
        }
      } else if (typeof value === 'object') {
        traverse(value, newPrefix);
      } else {
        parts.push(`${encode(newPrefix)}=${value !== undefined ? encode(value) : ''}`);
      }
    }
  }

  traverse(obj, '');
  return parts.join('&');
}

module.exports = { parseQuery, buildQuery };
