hjs-014.text:
I need to implement a Redux-style store that handles nested dispatches and subscriptions carefully. The key challenges are: (1) preventing dispatches from inside reducers by tracking a `dispatching` flag and throwing if violated, (2) snapshotting the subscriber list at the start of each dispatch so that subscriptions/unsubscriptions during notification don't affect the current round, and (3) allowing dispatches from subscribers by using a queue or recursive approach that completes the inner dispatch before resuming outer notification. I'll use a `currentListeners` array that gets replaced with a copy before each dispatch to ensure snapshot behavior, and track dispatch nesting level to detect invalid reducer dispatches.

ANSWER:
```javascript
function createStore(reducer, initial) {
  let state = typeof initial !== 'undefined' ? initial : reducer(undefined, { type: '@@INIT' });
  let currentListeners = [];
  let isDispatching = false;

  function getState() {
    return state;
  }

  function subscribe(listener) {
    if (typeof listener !== 'function') {
      throw new Error('Expected listener to be a function.');
    }

    let isSubscribed = true;

    currentListeners.push(listener);

    return function unsubscribe() {
      if (!isSubscribed) return;
      isSubscribed = false;

      const index = currentListeners.indexOf(listener);
      if (index > -1) {
        currentListeners.splice(index, 1);
      }
    };
  }

  function dispatch(action) {
    if (typeof action !== 'object' || action === null) {
      throw new Error('Actions must be plain objects. Use a custom middleware for async actions.');
    }

    if (isDispatching) {
      throw new Error('Reducers may not dispatch actions.');
    }

    try {
      isDispatching = true;

      // Snapshot listeners to prevent mutation during notification
      const listenersSnapshot = currentListeners.slice();

      state = reducer(state, action);

      // Notify listeners with snapshot
      for (let i = 0; i < listenersSnapshot.length; i++) {
        listenersSnapshot[i]();
      }

      return action;
    } finally {
      isDispatching = false;
    }
  }

  // Initialize with a dummy action to set initial state
  dispatch({ type: '@@INIT' });

  return { getState, dispatch, subscribe };
}

module.exports = createStore;
```

