hjs-015.text:
I'll approach this by first building a dependency graph to detect cycles and determine execution order. I'll use Kahn's algorithm for topological sorting, which naturally handles concurrency: tasks with no remaining dependencies can run in parallel. During graph construction, I'll validate that all dependencies exist (throwing an error with the missing name if not). For cycle detection, I'll track visited states (unvisited/visiting/visited) during DFS — if we revisit a "visiting" node, a cycle exists. When running tasks, I'll pass each task only the resolved values of its direct dependencies (not transitive ones), and if any task rejects, the overall promise rejects immediately while other independent tasks continue running (handled via Promise.allSettled for non-blocking execution of remaining tasks). Edge cases include empty task lists, self-references (a cycle), and ensuring rejected tasks don't block unrelated tasks.

ANSWER:
```javascript
function toposortTasks(tasks) {
  if (!tasks || typeof tasks !== 'object') {
    return Promise.reject(new Error('Invalid tasks input'));
  }

  const taskNames = Object.keys(tasks);
  if (taskNames.length === 0) {
    return Promise.resolve({});
  }

  // Build adjacency list and in-degree count
  const adj = {};
  const inDegree = {};
  for (const name of taskNames) {
    if (!tasks[name] || typeof tasks[name].deps !== 'object' || !Array.isArray(tasks[name].deps)) {
      throw new Error(`Invalid task definition for "${name}"`);
    }
    adj[name] = [];
    inDegree[name] = 0;
  }

  // Validate dependencies and build graph
  for (const name of taskNames) {
    const deps = tasks[name].deps;
    for (const dep of deps) {
      if (!(dep in tasks)) {
        throw new Error(`Unknown dependency "${dep}" for task "${name}"`);
      }
      adj[dep].push(name);
      inDegree[name]++;
    }
  }

  // Kahn's algorithm with cycle detection
  const queue = [];
  for (const name of taskNames) {
    if (inDegree[name] === 0) {
      queue.push(name);
    }
  }

  const topoOrder = [];
  while (queue.length > 0) {
    const node = queue.shift();
    topoOrder.push(node);
    for (const neighbor of adj[node]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
      }
    }
  }

  if (topoOrder.length !== taskNames.length) {
    throw new Error('cycle detected in dependencies');
  }

  // Execute tasks in topological order with concurrency
  const results = {};
  let error = null;

  // Group tasks by their depth (level in topological sort)
  const levels = {};
  for (let i = 0; i < topoOrder.length; i++) {
    const name = topoOrder[i];
    const deps = tasks[name].deps;
    let maxDepth = -1;
    for (const dep of deps) {
      if (levels[dep] !== undefined) {
        maxDepth = Math.max(maxDepth, levels[dep]);
      }
    }
    const depth = maxDepth + 1;
    levels[name] = depth;
    if (!levels[depth]) {
      levels[depth] = [];
    }
    levels[depth].push(name);
  }

  // Process level by level
  const maxLevel = Math.max(...Object.keys(levels).map(Number));

  for (let level = 0; level <= maxLevel; level++) {
    const currentLevelTasks = levels[level] || [];

    // Run tasks at this level concurrently
    const promises = currentLevelTasks.map(async (name) => {
      if (error) return; // Skip if already failed

      const deps = tasks[name].deps;
      const depValues = {};

      // Collect dependency results
      for (const dep of deps) {
        if (results[dep] === undefined && error) {
          return;
        }
        depValues[dep] = results[dep];
      }

      try {
        const result = await tasks[name].run(depValues);
        results[name] = result;
      } catch (e) {
        if (!error) {
          error = e;
        }
      }
    });

    await Promise.all(promises);

    // If any task in this level failed, reject immediately
    if (error) {
      throw error;
    }
  }

  return results;
}

module.exports = toposortTasks;
```

