hts-003.text:
I need to design a type-safe event bus where the payload type for each event key is strictly enforced. The core challenge is handling `void` payloads specially: when an event's payload type is `void`, the emit method should accept only one argument (the key), while for non-void payloads, it must require a second argument. I'll use function overloads and conditional types to distinguish between void and non-void payloads at both compile-time and runtime. At runtime, I'll check if the payload is undefined or absent to handle void events correctly.

```typescript
export class Bus<E extends Record<string, unknown>> {
  private handlers: Partial<Record<keyof E, Array<(payload: E[keyof E]) => void>>> = {};

  on<K extends keyof E>(key: K, fn: (payload: E[K]) => void): () => void {
    if (!this.handlers[key]) {
      this.handlers[key] = [];
    }
    this.handlers[key]?.push(fn as (payload: E[keyof E]) => void);

    return () => {
      const idx = this.handlers[key]?.indexOf(fn as (payload: E[keyof E]) => void);
      if (idx !== undefined && idx !== -1) {
        this.handlers[key]?.splice(idx, 1);
      }
    };
  }

  emit<K extends keyof E>(key: K): void;
  emit<K extends keyof E, P = E[K]>(key: K, payload: P): void;
  emit<K extends keyof E>(key: K, payload?: E[K]): void {
    const handlers = this.handlers[key];
    if (!handlers) return;

    for (const handler of handlers) {
      // For void payloads, call without arguments; otherwise pass payload
      if (payload === undefined && typeof payload !== 'object') {
        handler();
      } else {
        handler(payload as E[K]);
      }
    }
  }
}
