export module './sol' {
  export class Builder<Config extends Record<string, any>> {
    private _remainingRequiredKeys: keyof Config & string[] = [];
    private _setKeys = new Set<keyof Config>();
    private _values: Partial<Config> = {};
    private _built = false;

    constructor() {
      // Extract required keys (those not marked optional in Config)
      const keys = Object.keys({} as Config) as (keyof Config)[];
      this._remainingRequiredKeys = keys.filter(
        k => !(k in ({} as { [K in keyof Config as undefined extends Config[K] ? never : K } }))
      ) as any;
    }

    set<K extends keyof Config & string>(
      key: K,
      value: Config[K]
    ): Builder<
      Omit<Config, keyof Config & string> &
        { [K2 in keyof Config as K extends K2 ? never : K2]: Config[K2] }
    > {
      if (this._built) throw new Error('Builder already built');
      if (this._setKeys.has(key)) throw new Error(`Key "${String(key)}" already set`);
      if (!(key in ({} as Config))) throw new Error(`Unknown key: "${String(key)}"`);

      // Type-check value against Config[K]
      const typedValue = value as Config[keyof Config & string];

      this._setKeys.add(key);
      this._values[key] = typedValue;

      // Recompute remaining required keys
      const remainingRequiredKeys = this._remainingRequiredKeys.filter(
        k => k !== key && !(k in ({} as { [K in keyof Config as undefined extends Config[K] ? never : K } }))
      );

      return new Builder<Config>() as any;
    }

    build(): Config {
      if (this._built) throw new Error('Builder already built');
      if (this._remainingRequiredKeys.length > 0) {
        throw new Error(`Missing required keys: ${this._remainingRequiredKeys.join(', ')}`);
      }

      this._built = true;
      return this._values as Config;
    }
  }
