To handle deeply nested promises—including those inside objects, arrays, and mixed structures—we define a recursive type `DeepAwait<T>` that checks if `T` is a Promise, and if so, unwraps its resolved value recursively. For non-Promise types (including primitives, functions, objects without promises), it returns `T` unchanged. We must be careful with edge cases: functions should remain untouched (even if they return promises), arrays need recursive mapping, and objects require mapping over their keys recursively. The runtime `deepAwait` function mirrors this logic: it checks for Promise-ness, then recursively processes objects and arrays while leaving primitives and functions as-is.

ANSWER:
```typescript
export type DeepAwait<T> = T extends Promise<infer U>
  ? DeepAwait<U>
  : T extends object
  ? T extends Function
    ? T
    : T extends Array<infer E>
      ? Array<DeepAwait<E>>
      : { [K in keyof T]: DeepAwait<T[K]> }
  : T;

export async function deepAwait<T>(value: T): Promise<DeepAwait<T>> {
  if (value === null || typeof value !== 'object') {
    return value as DeepAwait<T>;
  }
  if (Array.isArray(value)) {
    const result: unknown[] = [];
    for (let i = 0; i < value.length; i++) {
      result[i] = await deepAwait(value[i]);
    }
    return result as DeepAwait<T>;
  }
  if (value instanceof Promise) {
    const resolved = await value;
    return deepAwait(resolved);
  }
  const result: Record<string, unknown> = {};
  for (const key in value) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      result[key] = await deepAwait((value as Record<string, unknown>)[key]);
    }
  }
  return result as DeepAwait<T>;
}
```

