type Brand<T, B extends string> = T & { [brandSymbol]: B };

const EmailBrandKey = 'Email' as const;

type Email = Brand<string, typeof EmailBrandKey>;

function isEmail(s: string): s is Email {
  if (typeof s !== 'string') return false;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(s)) return false;
  const e = s as Email;
  // Attach brand marker only if valid
  Object.defineProperty(e, brandSymbol, {
    value: EmailBrandKey,
    writable: false,
    enumerable: false,
    configurable: false
  });
  return true;
}

function asEmail(s: string): Email {
  if (!isEmail(s)) {
    throw new Error(`Invalid email address: "${s}"`);
  }
  return s as Email;
}

export { Brand, isEmail, asEmail, Email };
```

