To implement a discriminated union for `Result<T, E>`, I’ll define it as an object with a discriminant property (e.g., `type: 'ok' | 'err'`) to enable type narrowing via type guards. The `ok` and `err` constructors will return distinct tagged objects, ensuring that after `isOk(r)` returns true, TypeScript narrows the type to `{ type: 'ok'; value: T }`, and after `isErr(r)`, it narrows to `{ type: 'err'; error: E }`. This guarantees that accessing `.value` after `isErr(r)` is a compile-time error, satisfying the requirement. I’ll implement `map` to transform only the ok branch while preserving the error type, and `unwrapOr` to return the value if ok or a fallback otherwise.

ANSWER:
```typescript
export type Result<T, E> = 
  | { readonly type: 'ok'; readonly value: T }
  | { readonly type: 'err'; readonly error: E };

export function ok<T, E = never>(value: T): Result<T, E> {
  return { type: 'ok', value };
}

export function err<E, T = never>(error: E): Result<T, E> {
  return { type: 'err', error };
}

export function isOk<T, E>(result: Result<T, E>): result is { type: 'ok'; value: T } {
  return result.type === 'ok';
}

export function isErr<T, E>(result: Result<T, E>): result is { type: 'err'; error: E } {
  return result.type === 'err';
}

export function map<T, U, E>(result: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (isOk(result)) {
    return ok(fn(result.value));
  }
  return err(result.error);
}

export function unwrapOr<T, E>(result: Result<T, E>, defaultValue: T): T {
  return isOk(result) ? result.value : defaultValue;
}
