I need to implement a `DeepPartial<T>` type that makes all object properties optional recursively, while preserving arrays and functions as-is (i.e., not making their elements or signatures optional). For the runtime `applyPatch`, I must handle recursive merging of objects, replace arrays entirely (not merge them), and treat explicit `undefined` in the patch as "leave alone" — meaning if a property is explicitly set to `undefined`, it should not overwrite the base value. Edge cases include: handling null values (since typeof null === 'object'), ensuring arrays are replaced wholesale even if they contain objects, and preserving the exact type structure without widening.

ANSWER:
```typescript
export type DeepPartial<T> = T extends Function
  ? T
  : T extends Array<infer U>
  ? T
  : {
      [P in keyof T]?: DeepPartial<T[P]>;
    };

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === null || typeof patch !== 'object') {
    return base;
  }

  if (Array.isArray(patch)) {
    // Replace arrays wholesale
    return patch as T;
  }

  const result = { ...base } as T;

  for (const key in patch) {
    if (Object.prototype.hasOwnProperty.call(patch, key)) {
      const value = patch[key as keyof DeepPartial<T>];
      if (value === undefined) {
        // Explicit undefined means leave alone
        continue;
      }

      const baseValue = result[key as keyof T];
      if (
        baseValue !== null &&
        typeof baseValue === 'object' &&
        !Array.isArray(baseValue) &&
        value !== null &&
        typeof value === 'object' &&
        !Array.isArray(value)
      ) {
        // Recursively merge objects
        result[key as keyof T] = applyPatch(baseValue, value);
      } else {
        // Replace primitives, arrays, and other non-plain-objects
        result[key as keyof T] = value;
      }
    }
  }

  return result;
}
```

